// Package grpc contains the inbound ConnectRPC adapter for the traceability-service.
// NOTE: proto types are generated by buf generate.
package grpc

import (
	"context"

	"connectrpc.com/connect"
	"p9e.in/samavaya/packages/errors"
	"p9e.in/samavaya/packages/p9context"
	"p9e.in/samavaya/packages/p9log"

	// Generated by buf generate
	pb "p9e.in/samavaya/agriculture/traceability-service/api/v1"
	"p9e.in/samavaya/agriculture/traceability-service/api/v1/traceabilityv1connect"
	"p9e.in/samavaya/agriculture/traceability-service/internal/domain"
	"p9e.in/samavaya/agriculture/traceability-service/internal/ports/inbound"
)

// TraceabilityHandler is the ConnectRPC inbound adapter.
type TraceabilityHandler struct {
	traceabilityv1connect.UnimplementedTraceabilityServiceHandler
	svc inbound.TraceabilityService
	log *p9log.Helper
}

// NewTraceabilityHandler creates a new ConnectRPC traceability handler.
func NewTraceabilityHandler(svc inbound.TraceabilityService, log p9log.Logger) *TraceabilityHandler {
	return &TraceabilityHandler{
		svc: svc,
		log: p9log.NewHelper(p9log.With(log, "component", "TraceabilityHandler")),
	}
}

// CreateRecord handles creation requests.
func (h *TraceabilityHandler) CreateRecord(ctx context.Context, req *connect.Request[pb.CreateRecordRequest]) (*connect.Response[pb.CreateRecordResponse], error) {
	h.log.Infow("msg", "CreateRecord request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetFarmId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "farm_id is required")
	}
	entity := &domain.Traceability{Name: req.Msg.GetFarmId()}
	created, err := h.svc.CreateTraceability(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.CreateRecordResponse{Record: traceabilityToProto(created)}), nil
}

// GetRecord handles get requests.
func (h *TraceabilityHandler) GetRecord(ctx context.Context, req *connect.Request[pb.GetRecordRequest]) (*connect.Response[pb.GetRecordResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	entity, err := h.svc.GetTraceability(ctx, req.Msg.GetId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.GetRecordResponse{Record: traceabilityToProto(entity)}), nil
}

// ListRecords handles list requests.
func (h *TraceabilityHandler) ListRecords(ctx context.Context, req *connect.Request[pb.ListRecordsRequest]) (*connect.Response[pb.ListRecordsResponse], error) {
	params := domain.ListTraceabilityParams{PageSize: req.Msg.GetPageSize()}
	entities, total, err := h.svc.ListTraceabilitys(ctx, params)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	protos := make([]*pb.TraceabilityRecord, 0, len(entities))
	for i := range entities {
		protos = append(protos, traceabilityToProto(&entities[i]))
	}
	return connect.NewResponse(&pb.ListRecordsResponse{Records: protos, TotalCount: total}), nil
}

func traceabilityToProto(e *domain.Traceability) *pb.TraceabilityRecord {
	return &pb.TraceabilityRecord{
		Id:       e.UUID,
		TenantId: e.TenantID,
	}
}
